import {scenario,createSession,addEvent,finish,validateBackup,markdown,version,editScenario} from './workspace.js';
import {scenarios as builtins} from './engine.js';
const $=id=>document.getElementById(id),key='ghostlight-workspace-v2';let db={version,scenarios:builtins.map(s=>scenario({id:s.id,name:s.name,symptom:s.symptom,evidence:s.clue,resolution:({deploy:'Roll back v2.8.0, verify checkout success, and monitor error rate.',pool:'Pause the reporting job, release long-running transactions, and verify pool recovery.',storm:'Open a circuit breaker to stop retry amplification, then restore traffic gradually.'})[s.id],prevention:s.lesson,minutes:15})),sessions:[]},current=null,editingId=null,storageFailed=false;
function notice(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);}
try{const saved=localStorage.getItem(key);if(saved)db=validateBackup(JSON.parse(saved));}catch{storageFailed=true;notice('Saved data could not be loaded. The original data has been left untouched. Download a backup of new work before closing this page.',true);}
function persist(){if(storageFailed){notice('Browser storage is unavailable or unreadable. Download a backup before leaving; changes are held in memory.',true);return;}try{localStorage.setItem(key,JSON.stringify(db));notice('Saved in this browser · Download a backup to keep or transfer your work.');}catch{storageFailed=true;notice('Could not save. Download a backup before leaving this page.',true);}}
function el(tag,content,className){const node=document.createElement(tag);if(content!==undefined)node.textContent=content;if(className)node.className=className;return node;}
function button(label,handler,primary=false){const b=el('button',label,primary?'primary':'quiet');b.type='button';b.onclick=handler;return b;}
function view(name){for(const n of document.querySelectorAll('.view'))n.hidden=n.id!==name;for(const b of document.querySelectorAll('[data-view]'))b.classList.toggle('selected',b.dataset.view===name);if(name==='sessions')renderSessions();if(name==='library')renderLibrary();}
function openStart(id){const select=$('start-form').elements.scenario;select.replaceChildren(...db.scenarios.map(s=>{const o=el('option',s.name);o.value=s.id;return o;}));if(id)select.value=id;$('start-dialog').showModal();}
function openEdit(id){const s=db.scenarios.find(sc=>sc.id===id);if(!s)return;editingId=id;const form=$('scenario-form');form.elements.name.value=s.name;form.elements.symptom.value=s.symptom;form.elements.evidence.value=s.evidence;form.elements.resolution.value=s.resolution;form.elements.prevention.value=s.prevention;form.elements.minutes.value=s.minutes;form.querySelector('.form-error').textContent='';$('scenario-dialog-title').textContent='Edit scenario';$('scenario-dialog').showModal();}
function resetScenarioDialog(){editingId=null;$('scenario-form').reset();$('scenario-form').querySelector('.form-error').textContent='';$('scenario-dialog-title').textContent='Create a scenario';}
function renderLibrary(){$('scenario-list').replaceChildren(...db.scenarios.map(s=>{const c=el('div',undefined,'card');c.append(el('span',s.minutes+' MINUTE EXERCISE','badge'),el('h3',s.name),el('p',s.symptom),button('Start exercise',()=>openStart(s.id)),button('Edit scenario',()=>openEdit(s.id)));return c;}));}
function renderSessions(){const list=$('session-list');list.replaceChildren();if(!db.sessions.length){const empty=el('div',undefined,'empty-state');empty.append(el('h3','Your first rehearsal starts here.'),el('p','Pick a scenario, name your team, and capture what you learn.','muted'),button('Start an exercise',()=>openStart(),true));list.append(empty);return;}for(const s of [...db.sessions].reverse()){const c=el('div',undefined,'card');c.append(el('span',s.status==='active'?'IN PROGRESS':'COMPLETED','badge'),el('h3',s.scenario.name),el('p',s.commander+' · '+new Date(s.startedAt).toLocaleDateString()),el('p',`${s.events.length} timeline entries · ${s.followups.filter(f=>!f.done).length} open action items`,'muted'),button(s.status==='active'?'Continue exercise':'View postmortem',()=>{current=s.id;renderExercise();}));list.append(c);}}
function session(){return db.sessions.find(s=>s.id===current);}
function update(next){db.sessions=db.sessions.map(s=>s.id===next.id?next:s);persist();}
function field(label,name,value,handler){const l=el('label',label),t=el('textarea');t.name=name;t.value=value;t.maxLength=4000;t.oninput=()=>handler(t.value);l.append(t);return l;}
function renderExercise(){const s=session();if(!s)return view('sessions');view('exercise');const root=$('exercise');root.replaceChildren();const top=el('div',undefined,'section-heading'),head=el('div');head.append(el('p',s.status==='active'?'EXERCISE IN PROGRESS':'POSTMORTEM','eyebrow'),el('h2',s.scenario.name),el('p','Commander: '+s.commander,'muted'));top.append(head,button('Back to exercises',()=>view('sessions')));root.append(top);const toolbar=el('div',undefined,'toolbar');toolbar.append(el('span','','clock'));toolbar.firstChild.id='clock';toolbar.append(button('Export postmortem',()=>download(markdown(session()),'ghostlight-postmortem.md','text/markdown')));if(s.status==='active')toolbar.append(button('Complete exercise',()=>{update(finish(session()));renderExercise();},true));root.append(toolbar);
const grid=el('div',undefined,'exercise-grid'),left=el('div'),right=el('div');const brief=el('div',undefined,'box');brief.append(el('h3','Opening signal'),el('p',s.scenario.symptom));if(s.revealed)brief.append(el('h3','Investigation evidence'),el('p',s.scenario.evidence));else if(s.status==='active')brief.append(button('Reveal investigation evidence',()=>{let n=addEvent(session(),'evidence',s.scenario.evidence);n.revealed=true;update(n);renderExercise();}));left.append(brief);
const journal=el('div',undefined,'box');journal.style.marginTop='20px';journal.append(el('h3','Incident timeline'));for(const e of s.events){const d=el('div',undefined,'entry');d.append(el('small',new Date(e.at).toLocaleTimeString()+' · '+e.kind),el('p',e.body));journal.append(d);}if(!s.events.length)journal.append(el('p','Record observations, decisions, and communication as your team works through the incident.','muted'));if(s.status==='active'){const form=el('form');const label=el('label','Entry type'),select=el('select');select.name='kind';for(const kind of ['observation','decision','communication']){const o=el('option',kind);o.value=kind;select.append(o);}label.append(select);const bodyLabel=el('label','What happened?'),body=el('textarea');body.name='body';body.required=true;body.maxLength=4000;bodyLabel.append(body);const submit=el('button','Add timeline entry','primary');form.append(label,bodyLabel,submit);form.onsubmit=e=>{e.preventDefault();try{update(addEvent(session(),select.value,body.value));renderExercise();$('exercise').querySelector('textarea[name=body]')?.focus();}catch(error){notice(error.message,true);}};journal.append(form);}left.append(journal);
const review=el('div',undefined,'box');review.append(el('h3','Postmortem notes'),el('p','Capture the team’s understanding. These fields save as you type.','muted'),field('Impact and summary','summary',s.summary,v=>update({...session(),summary:v})),field('Root cause and contributing factors','rootCause',s.rootCause,v=>update({...session(),rootCause:v})));if(s.status==='complete'){review.append(el('h3','Facilitator guidance'),el('p',s.scenario.resolution),el('p',s.scenario.prevention,'muted'));}right.append(review);
const tasks=el('div',undefined,'box');tasks.style.marginTop='20px';tasks.append(el('h3','Follow-up action items'));for(const f of s.followups){const l=el('label',undefined,'followup'+(f.done?' done':'')),check=el('input');check.type='checkbox';check.checked=f.done;check.setAttribute('aria-label','Mark complete: '+f.task);check.onchange=()=>{update({...session(),followups:session().followups.map(x=>x.id===f.id?{...x,done:check.checked}:x)});l.classList.toggle('done',check.checked);};const span=el('span',f.task);span.append(el('small',f.owner||'Unassigned'));l.append(check,span);tasks.append(l);}const taskForm=el('form'),taskLabel=el('label','Action item'),task=el('input');task.required=true;task.maxLength=500;taskLabel.append(task);const ownerLabel=el('label','Owner'),owner=el('input');owner.maxLength=100;ownerLabel.append(owner);taskForm.append(taskLabel,ownerLabel,el('button','Add action item','quiet'));taskForm.onsubmit=e=>{e.preventDefault();if(session().followups.length>=100)return notice('Action item limit reached.',true);if(!task.value.trim())return;update({...session(),followups:[...session().followups,{id:crypto.randomUUID(),task:task.value.trim(),owner:owner.value.trim(),done:false}]});renderExercise();};tasks.append(taskForm);right.append(tasks);grid.append(left,right);root.append(grid);tick();}
function tick(){const s=session(),clock=$('clock');if(!s||!clock)return;const seconds=Math.max(0,Math.floor(((s.endedAt??Date.now())-s.startedAt)/1000)),remaining=s.scenario.minutes*60-seconds;clock.textContent=s.status==='complete'?`${Math.floor(seconds/60)}m ${seconds%60}s total`:remaining>=0?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} remaining`:`${Math.floor(-remaining/60)}m ${(-remaining)%60}s overtime`;}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>view(b.dataset.view);for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>{$(b.dataset.close).close();if(b.dataset.close==='scenario-dialog')resetScenarioDialog();};$('new-session').onclick=()=>openStart();$('new-scenario').onclick=()=>{resetScenarioDialog();$('scenario-dialog').showModal();};
$('scenario-form').onsubmit=e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.target));if(editingId){db=editScenario(db,editingId,fields);persist();resetScenarioDialog();$('scenario-dialog').close();renderLibrary();}else{if(db.scenarios.length>=100)throw Error('Scenario limit reached.');db.scenarios.push(scenario(fields));persist();resetScenarioDialog();$('scenario-dialog').close();renderLibrary();}}catch(error){e.target.querySelector('.form-error').textContent=error.message;}};
$('start-form').onsubmit=e=>{e.preventDefault();try{if(db.sessions.length>=200)throw Error('Exercise limit reached. Export a backup before starting a new workspace.');const values=Object.fromEntries(new FormData(e.target)),s=createSession(db.scenarios.find(s=>s.id===values.scenario),values.commander);db.sessions.push(s);current=s.id;persist();$('start-dialog').close();renderExercise();}catch(error){e.target.querySelector('.form-error').textContent=error.message;}};
$('backup').onclick=()=>download(JSON.stringify(db,null,2),'ghostlight-backup.json','application/json');$('restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Backup exceeds 5 MB.');const restored=validateBackup(JSON.parse(await file.text()));if(!confirm(`Replace this workspace with ${restored.sessions.length} exercises and ${restored.scenarios.length} scenarios? Download a backup first if you need your current data.`))return;db=restored;current=null;storageFailed=false;persist();view('sessions');}catch(error){notice('Restore failed: '+error.message,true);}finally{e.target.value='';}};
setInterval(tick,1000);renderSessions();
